/* ---------- drawer ---------- */
function openDrawer(id,tab){var m=M(id);if(!m)return;tab=tab||'overview';var s=status(m),t0=today().getTime(),dr=$('#drawer');
 var vis=S.checkins.filter(function(c){return c.mid===id});var pays=S.payments.filter(function(p){return p.mid===id}).sort(function(a,b){return b.date-a.date});
 var cal='';for(var d=34;d>=0;d--){var day=t0-d*DAY,hit=vis.some(function(c){return c.ts>=day&&c.ts<day+DAY});cal+='<i style="aspect-ratio:1;border-radius:5px;background:'+(hit?'var(--ac)':'var(--panel2)')+'" data-tip="'+dshort(day)+(hit?' · <b>visited</b>':'')+'"></i>'}
 var body={overview:'<div class="kv"><div><span>Plan</span><b>'+m.plan+'</b></div><div><span>Expires</span><b>'+dshort(m.expiry)+'</b></div><div><span>Trainer</span><b>'+esc(T(m.trainer).name.split(' ')[0])+'</b></div><div><span>Goal</span><b>'+m.goal+'</b></div><div><span>Member since</span><b>'+dshort(m.joined)+'</b></div><div><span>Phone</span><b class="mono">+91 '+m.phone.slice(0,5)+' ·····</b></div></div>'+
  '<div class="card" style="box-shadow:none"><div class="card-h"><h3>Progress · body weight</h3><span class="mono '+(m.weights[7]<m.weights[0]?'up':'')+'">'+(m.weights[7]-m.weights[0]>0?'+':'')+(m.weights[7]-m.weights[0]).toFixed(1)+' kg</span></div><div class="card-b">'+lineChart(m.weights,['W1','W2','W3','W4','W5','W6','W7','W8'],{h:170,min:Math.min.apply(0,m.weights)-2,label:'Weight progress',c:'#2DD4BF',tipf:function(v){return v+' kg'},fmt:function(v){return v.toFixed(0)}})+'</div></div>'+
  '<div class="card" style="box-shadow:none"><div class="card-h"><h3>Attendance · 5 weeks</h3><span class="mono mut">'+vis.filter(function(c){return c.ts>t0-35*DAY}).length+' visits</span></div><div class="card-b"><div style="display:grid;grid-template-columns:repeat(7,1fr);gap:4px">'+cal+'</div></div></div>',
  payments:pays.length?'<table class="t"><tbody>'+pays.map(function(p){return '<tr data-inv="'+p.id+'"><td class="mono">'+p.inv+'</td><td>'+p.plan+'</td><td class="mono mut">'+dshort(p.date)+'</td><td class="mono" style="text-align:right">'+inr(p.amount)+'</td></tr>'}).join('')+'</tbody></table>':'<div class="empty"><b>No payments yet</b></div>',
  notes:'<div class="fld"><label for="dn">Notes for the front desk</label><textarea class="inp" id="dn" rows="6" placeholder="Injuries, preferred slot, goals…">'+esc(m.notes)+'</textarea></div><button class="btn pri" data-act="saveNote" data-mid="'+id+'">Save note</button>'}[tab];
 dr.innerHTML='<div class="dr-h">'+av(m).replace('class="av"','class="av" style="width:52px;height:52px;font-size:17px;border-radius:16px;background:'+GRAD[m.g]+'"')+'<div style="min-width:0;flex:1"><h3>'+esc(m.name)+'</h3><div style="display:flex;gap:8px;align-items:center;margin-top:4px"><span class="pill '+s[1]+'">'+s[0]+'</span><span class="mono mut">'+m.id.toUpperCase()+' · PIN '+m.pin+'</span></div></div><button class="ib" data-act="closeDr" aria-label="Close profile">'+ic('x')+'</button></div>'+
 '<div style="padding:12px 24px 0;display:flex;gap:8px;flex-wrap:wrap"><button class="btn sm" data-act="editMember" data-mid="'+id+'">'+ic('edit')+'Edit</button><button class="btn sm" data-act="renew" data-mid="'+id+'">'+ic('rupee')+'Renew</button><a class="btn sm wa" target="_blank" rel="noopener noreferrer" href="'+waLink(m)+'">'+ic('wa')+'Reminder</a></div>'+
 '<div class="tabs" role="tablist" style="margin:12px 24px 0">'+['overview','payments','notes'].map(function(t){return '<button role="tab" aria-selected="'+(t==tab)+'" class="'+(t==tab?'on':'')+'" data-dtab="'+t+'" data-mid="'+id+'">'+t[0].toUpperCase()+t.slice(1)+'</button>'}).join('')+'</div><div class="dr-b">'+body+'</div>';
 dr.classList.add('on');dr.setAttribute('aria-hidden','false');$('#dbg').classList.add('on');bindTips(dr);var c=$('[data-act=closeDr]',dr);if(c&&!dr._open)c.focus();dr._open=1}
function closeDrawer(){var dr=$('#drawer');if(!dr)return;dr.classList.remove('on');dr.setAttribute('aria-hidden','true');dr._open=0;$('#dbg').classList.remove('on')}
function memberForm(m){m=m||{};var isNew=!m.id;
 modal(isNew?'Add member':'Edit member','<div class="fld"><label for="fn">Full name</label><input class="inp" id="fn" value="'+esc(m.name||'')+'" required></div><div class="f2"><div class="fld"><label for="fp">Phone</label><input class="inp" id="fp" inputmode="tel" value="'+esc(m.phone||'')+'"></div><div class="fld"><label for="fg">Goal</label><select class="inp" id="fg">'+['Fat loss','Muscle gain','General fitness','Strength','Mobility'].map(function(g){return '<option'+(m.goal==g?' selected':'')+'>'+g+'</option>'}).join('')+'</select></div></div><div class="f2"><div class="fld"><label for="fpl">Plan</label><select class="inp" id="fpl">'+Object.keys(PLANS).map(function(p){return '<option'+(m.plan==p?' selected':'')+'>'+p+'</option>'}).join('')+'</select></div><div class="fld"><label for="ft">Trainer</label><select class="inp" id="ft">'+S.trainers.map(function(t){return '<option value="'+t.id+'"'+(m.trainer==t.id?' selected':'')+'>'+esc(t.name)+'</option>'}).join('')+'</select></div></div><p class="mut" id="ferr" role="alert" style="margin:0;font-size:12.5px"></p>',
 '<button class="btn" data-x>Cancel</button><button class="btn pri" id="fsave">'+(isNew?'Add member':'Save changes')+'</button>',function(bg,close){$('#fsave',bg).addEventListener('click',function(){var n=$('#fn',bg).value.trim();if(n.length<3){$('#ferr',bg).textContent='Please enter the full name.';$('#fn',bg).focus();return}
  var plan=$('#fpl',bg).value;if(isNew){var id='m'+(1000+S.members.length+Math.floor(Math.random()*90+10)*10);m={id:id,name:n,phone:$('#fp',bg).value||'9800000000',gender:'M',plan:plan,start:today().getTime(),expiry:today().getTime()+PLANS[plan].d*DAY,joined:today().getTime(),trainer:$('#ft',bg).value,goal:$('#fg',bg).value,weights:[70,70,70,70,70,70,70,70],notes:'',g:Math.floor(Math.random()*6),pin:String(1000+S.members.length)};S.members.unshift(m);S.payments.push({id:'p'+Date.now(),inv:'IH-'+(2000+S.payments.length),mid:m.id,amount:PLANS[plan].p,date:Date.now(),mode:'UPI',plan:plan})}
  else{m.name=n;m.phone=$('#fp',bg).value;m.plan=plan;m.trainer=$('#ft',bg).value;m.goal=$('#fg',bg).value}
  save();close();toast(isNew?n+' added · PIN '+m.pin:'Changes saved');render();if(!isNew)openDrawer(m.id)})})}
/* ---------- command palette ---------- */
function cmd(){var acts=NAV.map(function(n){return {t:'Go to '+n[1],i:n[2],k:n[3],run:function(){location.hash='#/'+n[0]}}}).concat([{t:'Add member',i:'plus',run:function(){memberForm()}},{t:'Toggle light / dark theme',i:'sun',run:theme},{t:'Reset demo data',i:'reset',run:reset}]);
 var bg=D.createElement('div');bg.className='cmd-bg';bg.innerHTML='<div class="cmd" role="dialog" aria-modal="true" aria-label="Command palette"><label class="sr" for="ci">Search</label><input id="ci" placeholder="Type a command or member name…" autocomplete="off" role="combobox" aria-expanded="true" aria-controls="cl"><ul id="cl" role="listbox"></ul></div>';D.body.appendChild(bg);
 var inp=$('#ci',bg),ul=$('#cl',bg),sel=0,items=[];
 function draw(){var q=inp.value.toLowerCase();items=acts.filter(function(a){return a.t.toLowerCase().indexOf(q)>-1});if(q.length>1)items=items.concat(S.members.filter(function(m){return m.name.toLowerCase().indexOf(q)>-1}).slice(0,6).map(function(m){return {t:m.name,i:'users',k:m.plan,run:function(){location.hash='#/members';setTimeout(function(){openDrawer(m.id)},60)}}}));sel=Math.min(sel,Math.max(0,items.length-1));
  ul.innerHTML=items.length?items.map(function(a,i){return '<li role="option" aria-selected="'+(i==sel)+'" class="'+(i==sel?'on':'')+'" data-i="'+i+'">'+ic(a.i)+esc(a.t)+(a.k?'<small>'+esc(a.k)+'</small>':'')+'</li>'}).join(''):'<li class="mut">No results</li>'}
 function close(){bg.remove()}function go(i){var a=items[i];close();if(a)a.run()}
 inp.addEventListener('input',function(){sel=0;draw()});inp.addEventListener('keydown',function(e){if(e.key=='ArrowDown'){sel=Math.min(items.length-1,sel+1);draw();e.preventDefault()}else if(e.key=='ArrowUp'){sel=Math.max(0,sel-1);draw();e.preventDefault()}else if(e.key=='Enter'){go(sel)}else if(e.key=='Escape')close()});
 ul.addEventListener('click',function(e){var li=e.target.closest('[data-i]');if(li)go(+li.dataset.i)});bg.addEventListener('click',function(e){if(e.target===bg)close()});draw();inp.focus()}
function theme(){var h=D.documentElement,n=h.dataset.theme=='light'?'dark':'light';h.dataset.theme=n;try{localStorage.setItem('ih.theme',n)}catch(e){}render();toast((n=='light'?'Light':'Dark')+' theme')}
function reset(){S=seed();save();render();toast('Demo data reset')}
/* ---------- router ---------- */
var VIEWS={dashboard:vDash,members:vMembers,renewals:vRenewals,checkin:vCheckin,payments:vPayments,leads:vLeads,schedule:vSchedule,programs:vPrograms,reports:vReports,settings:vSettings};
function route(){var r=(location.hash.replace(/^#\/?/,'')||'').split('/')[0];var auth=localStorage.getItem('ih.auth');if(!auth)return 'login';return VIEWS[r]?r:'dashboard'}
var cur=null;
function render(){var r=route(),root=$('#root');if(r==='login'){root.innerHTML=vLogin();$('#lf').addEventListener('submit',function(e){e.preventDefault();localStorage.setItem('ih.auth','1');location.hash='#/dashboard';toast('Signed in to the demo')});cur=r;return}
 var y=r===cur?scrollY:0;root.innerHTML=shell(r,VIEWS[r]());cur=r;D.title=TITLES[r]+' · Ironhaus OS · Sample by Boozuka';bindTips(root);if(y)scrollTo(0,y);wire(r)}
function wire(r){var v=$('#view');
 if(r=='members'){var q=$('#mq'),tm;q.addEventListener('input',function(){clearTimeout(tm);tm=setTimeout(function(){MF.q=q.value;var p=q.selectionStart;render();var n=$('#mq');n.focus();n.setSelectionRange(p,p)},140)});$('#mp').addEventListener('change',function(e){MF.plan=e.target.value;render()})}
 if(r=='leads')wireKanban();
 $$('tr[data-mid]',v).forEach(function(tr){tr.addEventListener('keydown',function(e){if(e.key=='Enter')openDrawer(tr.dataset.mid)})});}
function wireKanban(){var ghost=null,start=null,card=null,over=null;
 $$('.lead').forEach(function(c){c.addEventListener('pointerdown',function(e){if(e.button)return;card=c;start=[e.clientX,e.clientY];c.setPointerCapture(e.pointerId)});
  c.addEventListener('pointermove',function(e){if(!card||card!==c)return;if(!ghost){if(Math.hypot(e.clientX-start[0],e.clientY-start[1])<6)return;ghost=c.cloneNode(true);ghost.classList.add('ghost');D.body.appendChild(ghost);c.classList.add('drag')}ghost.style.left=(e.clientX-120)+'px';ghost.style.top=(e.clientY-30)+'px';ghost.style.display='none';var el=D.elementFromPoint(e.clientX,e.clientY);ghost.style.display='';var col=el&&el.closest('.col');$$('.col').forEach(function(x){x.classList.toggle('over',x===col)});over=col});
  c.addEventListener('pointerup',function(){if(ghost){ghost.remove();ghost=null;c.classList.remove('drag');$$('.col').forEach(function(x){x.classList.remove('over')});if(over){var l=S.leads.filter(function(x){return x.id===c.dataset.lid})[0];if(l.stage!==over.dataset.stage){l.stage=over.dataset.stage;save();toast(l.name+' moved to '+l.stage);render()}}}card=null;over=null});
  c.addEventListener('keydown',function(e){var ord=['New','Trial','Joined','Lost'];var l=S.leads.filter(function(x){return x.id===c.dataset.lid})[0];var i=ord.indexOf(l.stage);if(e.key=='ArrowRight'&&i<3)i++;else if(e.key=='ArrowLeft'&&i>0)i--;else return;e.preventDefault();l.stage=ord[i];save();render();toast(l.name+' moved to '+l.stage);var n=$('[data-lid="'+l.id+'"]');if(n)n.focus()})})}
D.addEventListener('click',function(e){var a=e.target.closest('[data-act]'),t;
 if(a){var act=a.dataset.act;if(act!='more')e.preventDefault();
  if(act=='cmd')cmd();else if(act=='theme')theme();else if(act=='reset'){reset()}else if(act=='logout'){localStorage.removeItem('ih.auth');location.hash='#/login';render()}
  else if(act=='addMember')memberForm();else if(act=='editMember')memberForm(M(a.dataset.mid));else if(act=='closeDr')closeDrawer();else if(act=='toast')toast(a.dataset.msg);
  else if(act=='clearF'){MF={q:'',plan:'',st:'',sort:'name'};render()}
  else if(act=='saveNote'){M(a.dataset.mid).notes=$('#dn').value;save();toast('Note saved')}
  else if(act=='renew'){var m=M(a.dataset.mid),base=Math.max(m.expiry,today().getTime());m.expiry=base+PLANS[m.plan].d*DAY;var p={id:'p'+Date.now(),inv:'IH-'+(3000+S.payments.length),mid:m.id,amount:PLANS[m.plan].p,date:Date.now(),mode:'UPI',plan:m.plan};S.payments.push(p);save();toast(m.name+' renewed till '+dshort(m.expiry));render();openDrawer(m.id,'payments')}
  else if(act=='more'){e.preventDefault();modal('More','<div class="g">'+NAV.filter(function(n){return ['dashboard','members','checkin','leads'].indexOf(n[0])<0}).map(function(n){return '<a class="btn" style="justify-content:flex-start;height:44px" href="#/'+n[0]+'" data-x>'+ic(n[2])+n[1]+'</a>'}).join('')+'<button class="btn" style="justify-content:flex-start;height:44px" data-act="theme" data-x>'+ic('sun')+'Toggle theme</button><button class="btn" style="justify-content:flex-start;height:44px" data-act="logout" data-x>'+ic('out')+'Sign out</button></div>')}
  else if(act=='newPay'){modal('Record payment','<div class="fld"><label for="pm">Member</label><select class="inp" id="pm">'+S.members.slice(0,40).map(function(m){return '<option value="'+m.id+'">'+esc(m.name)+' · '+m.plan+'</option>'}).join('')+'</select></div><div class="fld"><label for="pmo">Mode</label><select class="inp" id="pmo"><option>UPI</option><option>Cash</option><option>Card</option></select></div>','<button class="btn" data-x>Cancel</button><button class="btn pri" id="psave">Save &amp; preview invoice</button>',function(bg,close){$('#psave',bg).addEventListener('click',function(){var m=M($('#pm',bg).value);var p={id:'p'+Date.now(),inv:'IH-'+(3000+S.payments.length),mid:m.id,amount:PLANS[m.plan].p,date:Date.now(),mode:$('#pmo',bg).value,plan:m.plan};S.payments.push(p);save();close();render();toast('Payment recorded');showInv(p)})})}
  else if(act=='addLead'){modal('Add lead','<div class="fld"><label for="ln">Name</label><input class="inp" id="ln"></div><div class="f2"><div class="fld"><label for="lsrc">Source</label><select class="inp" id="lsrc"><option>Walk-in</option><option>Instagram ad</option><option>Google Maps</option><option>Referral</option><option>WhatsApp</option></select></div><div class="fld"><label for="lint">Interest</label><select class="inp" id="lint">'+Object.keys(PLANS).map(function(p){return '<option>'+p+'</option>'}).join('')+'</select></div></div>','<button class="btn" data-x>Cancel</button><button class="btn pri" id="lsave">Add lead</button>',function(bg,close){$('#lsave',bg).addEventListener('click',function(){var n=$('#ln',bg).value.trim();if(!n){$('#ln',bg).focus();return}S.leads.unshift({id:'l'+Date.now(),name:n,src:$('#lsrc',bg).value,stage:'New',interest:$('#lint',bg).value,date:Date.now()});save();close();render();toast('Lead added')})})}
  return}
 if(e.target.closest('#dbg')){closeDrawer();return}
 if((t=e.target.closest('[data-dtab]'))){openDrawer(t.dataset.mid,t.dataset.dtab);return}
 if((t=e.target.closest('tr[data-mid]'))&&!e.target.closest('a')){openDrawer(t.dataset.mid);return}
 if((t=e.target.closest('tr[data-inv]'))){showInv(S.payments.filter(function(p){return p.id===t.dataset.inv})[0]);return}
 if((t=e.target.closest('[data-st]'))){MF.st=t.dataset.st;render();return}
 if((t=e.target.closest('[data-sort]'))){MF.sort=MF.sort=='expiry'?'name':'expiry';render();return}
 if((t=e.target.closest('[data-win]'))){sessionStorage.setItem('ih.win',t.dataset.win);render();return}
 if((t=e.target.closest('[data-wa]'))){toast('Reminder opened in WhatsApp');return}
 if((t=e.target.closest('[data-k]'))){var k=t.dataset.k;if(k=='C')KI.code='';else if(k=='OK'){if(KI.code.length==4)return doCheckin(KI.code)}else if(KI.code.length<4)KI.code+=k;$('#kcode').innerHTML=KI.code.replace(/./g,'•')||'<span class="mut">····</span>';if(KI.code.length==4&&k!='OK')setTimeout(function(){doCheckin(KI.code)},180);return}
 if((t=e.target.closest('[data-pin]'))){doCheckin(t.dataset.pin);return}
 if((t=e.target.closest('[data-cls]'))){var pr=t.dataset.cls.split('-');var c=S.classes.filter(function(x){return x.day==pr[0]&&x.hr==pr[1]})[0];if(c.booked>=c.cap){toast(c.name+' is full');return}c.booked++;save();render();toast('1 spot booked in '+c.name)}
});
